// Parse Google Vision OCR text into structured receipt items
const response   = $input.first().json;
const fullText   = response?.responses?.[0]?.fullTextAnnotation?.text
                || response?.responses?.[0]?.textAnnotations?.[0]?.description
                || '';

if (!fullText) {
  throw new Error('OCR returned no text. Check image quality or API key.');
}

const lines = fullText.split('\n').map(l => l.trim()).filter(Boolean);

// ── Parsing heuristics ──────────────────────────────────────
// Match patterns like:
//   Burger         R45.00
//   Beer x2        R90.00
//   Cola x 3       R75.00
//   Chips          45.00
//   TOTAL          R355.00  (ignored)
const SKIP_WORDS = ['total', 'subtotal', 'vat', 'tax', 'service', 'gratuity',
                    'discount', 'change', 'cash', 'card', 'tip'];

const priceRe = /[Rr]?\s*(\d{1,6}(?:[.,]\d{2})?)/;
const qtyRe   = /[xX×]\s*(\d+)$/;

const items = [];

for (const line of lines) {
  const lower = line.toLowerCase();
  // Skip summary lines
  if (SKIP_WORDS.some(w => lower.includes(w))) continue;

  const priceMatch = line.match(/[Rr]\s*(\d{1,6}(?:[.,]\d{2})?)\s*$/);
  if (!priceMatch) continue;

  const priceStr    = priceMatch[1].replace(',', '.');
  const priceFloat  = parseFloat(priceStr);
  if (isNaN(priceFloat) || priceFloat <= 0) continue;

  // Extract quantity if present
  let name  = line.replace(priceMatch[0], '').trim();
  let qty   = 1;
  const qm  = name.match(qtyRe);
  if (qm) {
    qty  = parseInt(qm[1], 10);
    name = name.replace(qm[0], '').trim();
  }

  // Clean name
  name = name.replace(/\.+/g, '').trim();
  if (!name || name.length < 2) continue;

  // unit_price is the per-unit price (price on receipt is total for qty)
  const unitPriceCents = Math.round((priceFloat / qty) * 100);

  items.push({
    name:             name.charAt(0).toUpperCase() + name.slice(1).toLowerCase(),
    unit_price_cents: unitPriceCents,
    total_quantity:   qty
  });
}

if (items.length === 0) {
  throw new Error('No receipt items could be parsed. Check image quality.');
}

const guest = $('Validate Host Token').first().json;

return [{
  json: {
    party_id: guest.party_id,
    items
  }
}];

// Build a bulk INSERT SQL for all parsed items
const { party_id, items } = $('Parse OCR Items').first().json;

if (!items || items.length === 0) {
  throw new Error('No items to insert');
}

const params = [];
const valueParts = items.map((item, i) => {
  const base = i * 3;
  params.push(party_id, item.name, item.unit_price_cents);
  // total_quantity is stored; quantity supplied per item
  return `(uuid_generate_v4(), $${base+1}::uuid, $${base+2}, $${base+3}, ${item.total_quantity})`;
});

const sql = `INSERT INTO items (id, party_id, name, unit_price_cents, total_quantity) VALUES ${valueParts.join(', ')} RETURNING id, name, unit_price_cents, total_quantity`;

return [{ json: { sql, params, party_id, items } }];
